Функция ПолучитьСальдоСчета(СсылкаНаСчет)
	ЗапросД = Новый Запрос;
	ЗапросД.Текст = "ВЫБРАТЬ
	|	СУММА(ХОЗРАСЧЕТНЫЙ.Сумма) КАК Дебет
	|ИЗ
	|	РегистрБухгалтерии.Хозрасчетный КАК ХОЗРАСЧЕТНЫЙ
	|ГДЕ
	|	ХОЗРАСЧЕТНЫЙ.СчетДт В ИЕРАРХИИ &Счет";
	ЗапросД.УстановитьПараметр("Счет", СсылкаНаСчет);
	Дебет = ЗапросД.Выполнить().Поле(0);
	Если Дебет = Неопределено Тогда Дебет = 0; КонецЕсли;

	ЗапросК = Новый Запрос;
	ЗапросК.Текст = "ВЫБРАТЬ
	|	СУММА(ХОЗРАСЧЕТНЫЙ.Сумма) КАК Кредит
	|ИЗ
	|	РегистрБухгалтерии.Хозрасчетный КАК ХОЗРАСЧЕТНЫЙ
	|ГДЕ
	|	ХОЗРАСЧЕТНЫЙ.СчетКт В ИЕРАРХИИ &Счет";
	ЗапросК.УстановитьПараметр("Счет", СсылкаНаСчет);
	Кредит = ЗапросК.Выполнить().Поле(0);
	Если Кредит = Неопределено Тогда Кредит = 0; КонецЕсли;

	ВидСчета = СсылкаНаСчет.Вид;
	Если ВидСчета = ВидСчета.Пассивный Тогда
		Сальдо = Кредит - Дебет;
	Иначе
		Сальдо = Дебет - Кредит;
	КонецЕсли;

	Возврат Сальдо;
КонецФункции
